package com.midtermwork;
import org.junit.Test;
import static org.junit.Assert.*;
public class CombatFeedbackChecks {
 private GameWorld world(){GameWorld w=new GameWorld();w.enemies.clear();w.spikes.clear();w.setDropSeed(0);return w;}
 private GameWorld.Enemy target(GameWorld w,GameWorld.Phase phase){GameWorld.Enemy e=new GameWorld.Enemy(180,112,true);e.hp=e.maxHp=10000;e.timer=1000;e.phase=phase;w.enemies.add(e);return e;}
 private void hit(GameWorld w,GameWorld.Enemy e,GameWorld.Skill m) throws Exception{java.lang.reflect.Method f=GameWorld.class.getDeclaredMethod("playerHit",GameWorld.Enemy.class,int.class,int.class,GameWorld.Skill.class);f.setAccessible(true);f.invoke(w,e,20,1,m);}
 private void basic(GameWorld w){w.step(1f/60,0,false,true);for(int i=0;i<20;i++)w.step(1f/60,0,false,false);}
 @Test public void actualBasicAttackExplainsGuardAndCounterBonus(){GameWorld w=world();target(w,GameWorld.Phase.WINDUP);basic(w);assertEquals(GameWorld.CombatKind.GUARDED,w.combatTexts.get(0).kind);assertTrue(w.combatTexts.get(0).label.contains("평타 방어"));assertEquals(GameWorld.SoundCue.GUARDED,w.drainSoundCues().get(0));w=world();target(w,GameWorld.Phase.RECOVER);basic(w);assertEquals(GameWorld.CombatKind.COUNTER,w.combatTexts.get(0).kind);assertTrue(w.combatTexts.get(0).label.contains("빈틈 공격"));assertEquals(GameWorld.SoundCue.COUNTER,w.drainSoundCues().get(0));}
 @Test public void rangedAttacksDoNotFalselyClaimCounterBonus() throws Exception{GameWorld w=world();GameWorld.Enemy e=target(w,GameWorld.Phase.RECOVER);hit(w,e,GameWorld.Skill.EMBER);assertEquals(GameWorld.CombatKind.NORMAL,w.combatTexts.get(0).kind);}
 @Test public void weaknessCriticalAndImmunityHaveDistinctFeedback() throws Exception{GameWorld w=world();GameWorld.Enemy e=target(w,GameWorld.Phase.PATROL);e.primaryType=GameWorld.Element.NORMAL;hit(w,e,GameWorld.Skill.BRICK_BREAK);assertEquals(GameWorld.CombatKind.WEAKNESS,w.combatTexts.get(0).kind);assertTrue(w.combatTexts.get(0).label.contains("효과 굉장"));w=world();e=target(w,GameWorld.Phase.PATROL);for(int i=0;i<100;i++)w.collectItem(GameWorld.Item.SCOPE);hit(w,e,GameWorld.Skill.EMBER);assertEquals(GameWorld.CombatKind.CRITICAL,w.combatTexts.get(0).kind);assertEquals(GameWorld.SoundCue.CRITICAL,w.drainSoundCues().get(0));w=world();e=target(w,GameWorld.Phase.PATROL);e.primaryType=GameWorld.Element.GHOST;hit(w,e,GameWorld.Skill.SCRATCH);assertEquals(10000,e.hp);assertEquals(GameWorld.CombatKind.IMMUNE,w.combatTexts.get(0).kind);assertEquals(GameWorld.SoundCue.IMMUNE,w.drainSoundCues().get(0));}
 @Test public void killTextSurvivesEnemyAndUsesActualHpLoss() throws Exception{GameWorld w=world();GameWorld.Enemy e=target(w,GameWorld.Phase.PATROL);e.hp=1;hit(w,e,GameWorld.Skill.EMBER);assertFalse(e.alive());assertEquals("-1",w.combatTexts.get(0).label);assertFalse(w.drainSoundCues().isEmpty());assertTrue(w.drainSoundCues().isEmpty());}
 @Test public void hurtFeedbackDoesNotRepeatDuringInvulnerability(){GameWorld w=world();w.damage(1,200);assertEquals(GameWorld.CombatKind.HURT,w.combatTexts.get(0).kind);assertEquals(GameWorld.SoundCue.HURT,w.drainSoundCues().get(0));w.damage(1,200);assertTrue(w.drainSoundCues().isEmpty());}
 @Test public void bossWarningIsEmittedOncePerWindup(){GameWorld w=world();w.mapIndex=4;w.stageComplete=true;w.advanceStage();w.bossActive=true;w.boss.timer=0;w.step(1f/60,0,false,false);assertEquals(GameWorld.SoundCue.BOSS_WARNING,w.drainSoundCues().get(0));for(int i=0;i<10;i++)w.step(1f/60,0,false,false);assertTrue(w.drainSoundCues().isEmpty());}
 @Test public void feedbackFreezesInPauseAndQueuesAreBounded() throws Exception{GameWorld w=world();GameWorld.Enemy e=target(w,GameWorld.Phase.PATROL);for(int i=0;i<100;i++)hit(w,e,GameWorld.Skill.EMBER);assertEquals(32,w.combatTexts.size());assertEquals(32,w.drainSoundCues().size());w.paused=true;float age=w.combatTexts.get(0).age;w.step(1f/30,0,false,false);assertEquals(age,w.combatTexts.get(0).age,0);w.restart();assertTrue(w.combatTexts.isEmpty());assertTrue(w.drainSoundCues().isEmpty());}
}
